import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);if q.count==1{q.firstMatch.tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name);return};b.tap()}
 func type(_ field:XCUIElement,_ value:String){field.tap();for c in value{field.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
 func testSameAppServerRAMLossKeepsUnsentText() throws {
 continueAfterFailure=false
 let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();let decline=app.buttons["Decline analytics"];if decline.waitForExistence(timeout:2){decline.tap()};tap(app,"Profile, tab, 5 of 5");XCTAssertTrue(app.buttons["Sign in or create an account"].waitForExistence(timeout:10));tap(app,"Ask Fancy");tap(app,"Start conversation");let q=app.textViews["Ask Fancy a question"];XCTAssertTrue(q.waitForExistence(timeout:12));type(q,"Find meals for me.");tap(app,"Ask");let reply=app.staticTexts.matching(NSPredicate(format:"label BEGINSWITH %@","No eligible public meals match")).firstMatch;XCTAssertTrue(reply.waitForExistence(timeout:25),app.debugDescription);XCTAssertEqual(q.value as? String,"");let unsent="QA034 LIVE UNSENT91";type(q,unsent);XCTAssertEqual(q.value as? String,unsent);tap(app,"Close");let dir=NSTemporaryDirectory();let ready=dir+"qa034-91-ready.json",go=dir+"qa034-91-continue.json";try? FileManager.default.removeItem(atPath:go);try "{\"run\":91,\"ready\":true}".write(toFile:ready,atomically:true,encoding:.utf8);print("QA034_READY91="+ready);fflush(stdout)
 let limit=Date().addingTimeInterval(150);while !FileManager.default.fileExists(atPath:go) && Date()<limit{Thread.sleep(forTimeInterval:0.2)};XCTAssertTrue(FileManager.default.fileExists(atPath:go),"QA orchestration gate timed out; not a business-response timeout");tap(app,"Ask Fancy");tap(app,"Continue conversation");let expired=app.buttons["Start again with my unsent text"];XCTAssertTrue(expired.waitForExistence(timeout:15),app.debugDescription);XCTAssertEqual(q.value as? String,unsent);XCTAssertFalse(reply.exists);XCTAssertFalse(app.buttons["Retry assistant request"].exists);print("QA_NATIVE91_SAME_APP_RAMLOSS_EXPIRED_UNSENT_NO_AUTO_NEW\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native91-ramloss-expired-unsent";a.lifetime = .keepAlways;add(a)
 }
